import os, re
from pathlib import Path

repo = Path("/bench/repo")
entities = [
    "User", "UserSetting", "UserIdentity", "Memo", "MemoRelation", 
    "MemoShare", "Attachment", "Reaction", "Inbox", "IdentityProvider", "InstanceSetting"
]

# Build patterns for each entity - store.Entity, *store.Entity, store.FindEntity, etc.
def entity_patterns(name):
    patterns = [
        rf'\bstore\.{name}\b',
        rf'\*store\.{name}\b',
        rf'\bstore\.Find{name}\b',
        rf'\bstore\.Update{name}\b',
        rf'\bstore\.Delete{name}\b',
    ]
    return [re.compile(p) for p in patterns]

entity_pats = {e: entity_patterns(e) for e in entities}

# Collect go files outside store/
files_by_pkg = {}
for root, dirs, files in os.walk(repo):
    if '/store/' in root.replace('\\', '/') or root.endswith('/store'):
        continue
    for f in files:
        if f.endswith('.go'):
            fp = Path(root) / f
            rel = fp.relative_to(repo)
            # package = directory path
            pkg = str(rel.parent)
            content = fp.read_text(errors='ignore')
            if 'github.com/usememos/memos/store' not in content:
                continue
            files_by_pkg.setdefault(pkg, []).append((fp, content))

# Count packages per entity
results = {e: set() for e in entities}
for pkg, file_list in files_by_pkg.items():
    combined = '\n'.join(c for _, c in file_list)
    for entity, pats in entity_pats.items():
        if any(p.search(combined) for p in pats):
            results[entity].add(pkg)

